BEGIN;
CREATE FUNCTION universe.issue_credential(tenant uuid,subject uuid,kind text,digest text,scopes text[],days integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE result uuid;BEGIN IF tenant<>nullif(current_setting('universe.tenant_id',true),'')::uuid THEN RAISE EXCEPTION 'Tenant mismatch';END IF;INSERT INTO universe.credentials(tenant_id,subject_id,kind,token_hash,scopes,expires_at)VALUES(tenant,subject,kind,digest,scopes,now()+days*interval '1 day')RETURNING id INTO result;RETURN result;END$$;
CREATE FUNCTION universe.rotate_credential(tenant uuid,credential uuid,digest text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF tenant<>nullif(current_setting('universe.tenant_id',true),'')::uuid THEN RAISE EXCEPTION 'Tenant mismatch';END IF;UPDATE universe.credentials SET token_hash=digest WHERE id=credential AND tenant_id=tenant AND revoked_at IS NULL AND expires_at>now();IF NOT FOUND THEN RAISE EXCEPTION 'Credential unavailable';END IF;END$$;
REVOKE ALL ON FUNCTION universe.issue_credential(uuid,uuid,text,text,text[],integer),universe.rotate_credential(uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION universe.issue_credential(uuid,uuid,text,text,text[],integer),universe.rotate_credential(uuid,uuid,text) TO universe_api;
INSERT INTO universe.migrations(version)VALUES('002_credentials');COMMIT;
